service.method:

			INSERT INTO SDPLN (
			       DEPLOY_ID
			      ,MODULE_NAME
			      ,SOURCE_BASE_DIR
			      ,TARGET_BASE_DIR
			      ,"ORDER"
			      ,USE_YN
			      ,ADD_DATE
			      ,ADD_TIME
			      ,ADD_USER_ID
			      ,CHANGE_DATE
			      ,CHANGE_TIME
			      ,CHANGE_USER_ID
		  ) VALUES (
        		  ${DEPLOY_ID}
        		 ,${MODULE_NAME_TMP}
        		 ,${FROM}
        		 ,${TO}
        		 ,${ORDER}
			     ,(CASE WHEN ${USE_YN} = '1' THEN 'Y' ELSE 'N' END)
        		 ,${current.date}
        		 ,${current.time}
        		 ,${session.ID}
        		 ,${current.date}
        		 ,${current.time}
        		 ,${session.ID}
	        )


			INSERT INTO SDPSE (
			       DEPLOY_ID
			      ,MODULE_NAME
			      ,SEQ
			      ,"FROM"
			      ,"TO"
			      ,INCLUDE
			      ,EXCLUDE
			      ,SCRIPT
			      ,"ORDER"
			      ,USE_YN
			      ,ADD_DATE
			      ,ADD_TIME
			      ,ADD_USER_ID
			      ,CHANGE_DATE
			      ,CHANGE_TIME
			      ,CHANGE_USER_ID
		  ) VALUES (
        		  ${DEPLOY_ID}
        		 ,${MODULE_NAME_TMP}
        		 ,${SEQ}
        		 ,${FROM}
        		 ,${TO}
        		 ,${INCLUDE}
        		 ,${EXCLUDE}
        		 ,${SCRIPT}
        		 ,${ORDER}
			     ,(CASE WHEN ${USE_YN} = '1' THEN 'Y' ELSE 'N' END)
        		 ,${current.date}
        		 ,${current.time}
        		 ,${session.ID}
        		 ,${current.date}
        		 ,${current.time}
        		 ,${session.ID}
	        )


UPDATE  SDPGL
   SET  
   	   SERVER_URL = ${SERVER_URL}
      ,DESCRIPTION = ${DESCRIPTION}
      ,CHANGE_DATE = ${current.DATE}
      ,CHANGE_TIME = ${current.TIME}
      ,CHANGE_USER_ID = ${session.ID}
      ,SOURCE_TEMP_DIR = ${SOURCE_TEMP_DIR}
      ,TARGET_TEMP_DIR = ${TARGET_TEMP_DIR}
 WHERE DEPLOY_ID = ${DEPLOY_ID}
